mapper.select:
SELECT id, username, user_id, login_at, login_ip, user_agent,
       status, fail_reason, mfa_used, mfa_success, trace_id, tenant_id, created_at
FROM ydsz_login_audit
WHERE username = #{username}
ORDER BY login_at DESC
LIMIT #{limit}

SELECT COUNT(*) FROM ydsz_login_audit
WHERE login_ip = #{ip}
  AND status = #{status}
  AND login_at > (CURRENT_TIMESTAMP - (#{sinceMinutes} || ' minute')::interval)
